mapper.select:
SELECT DISTINCT q.* FROM questions q
LEFT JOIN categories c ON c.id = q.category_id
LEFT JOIN question_tags qt ON qt.question_id = q.id LEFT JOIN tags t ON t.id = qt.tag_id
AND q.creator_id = #{q.ownerId}
AND q.category_id = #{q.categoryId}
AND q.difficulty = #{q.difficulty}
AND q.question_type = #{q.questionType}
AND t.id = #{q.tagId}
AND ( q.title LIKE CONCAT('%', #{q.keyword}, '%') OR q.answer LIKE CONCAT('%', #{q.keyword}, '%') OR q.explanation LIKE CONCAT('%', #{q.keyword}, '%') OR c.name LIKE CONCAT('%', #{q.keyword}, '%') OR t.name LIKE CONCAT('%', #{q.keyword}, '%') )
ORDER BY
q.usage_count q.title
CASE q.difficulty WHEN 'easy' THEN 1 WHEN 'medium' THEN 2 WHEN 'hard' THEN 3 ELSE 99 END
COALESCE(q.updated_at, q.created_at) q.created_at
ASC DESC
, q.id DESC
